  let result = '';
  let i = 0;
  while (i < text.length) {
    // Check if it's a percent-triplet
    if (text[i] === '%' && i + 2 < text.length && /[0-9A-Fa-f]{2}/.test(text.slice(i + 1, i + 3))) {
      result += text.slice(i, i + 3);
      i += 3;
    } else {
